import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Full-history opponent statistics
    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Endgame: last round, exploit a cooperative opponent
    if n == 100:
        if opp_d * 4 < n:
            return 'D'
        return 'C'

    # Near the end, tilt toward exploitation when opponent is cooperative
    if n >= 95:
        if opp_d * 5 < n:
            return 'D'
        return 'C'

    # Detect near-always-defector
    if opp_d * 10 >= n * 9 and n >= 10:
        return 'D'

    # Detect near-always-cooperator: mostly cooperate, occasional exploit
    if opp_d == 0 and n >= 20:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Immediate retaliation on defection, with limited forgiveness
    if opp_last == 'D':
        # If opponent has defected many times recently, keep punishing
        recent_n = 8 if n >= 8 else n
        recent_d = 0
        for i in range(n - recent_n, n):
            if history[i][1] == 'D':
                recent_d += 1
        if recent_d >= 4:
            return 'D'
        # Forgiveness: if opponent was largely cooperative before, one-round punish
        if opp_d * 10 < n:
            return 'D'
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    # If we just punished and opponent returned to C, cooperate back
    if my_last == 'D' and opp_last == 'C':
        return 'C'

    # If opponent has a moderate defect rate, sometimes probe
    if opp_d * 4 >= n and n >= 10:
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    # Mostly cooperate against cooperative opponents
    if n >= 30 and my_d * 5 < n and opp_d * 5 < n:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'
